// Context: A synthesizer with a user-configurable modulation matrix connects
// global LFOs and envelopes from a GlobalModulatorContainer to per-oscillator
// gain and pitch chains. Each connection is created dynamically when the user
// enables a routing in the modulation matrix UI.

// Global modulation sources from a GlobalModulatorContainer
const var globalLFO1 = Synth.getModulator("GlobalLFO1");
const var globalLFO2 = Synth.getModulator("GlobalLFO2");

// Modulation targets - child synth oscillator groups
const var osc1 = Synth.getChildSynth("Oscillator1");
const var osc2 = Synth.getChildSynth("Oscillator2");

// Chain indices: 1 = GainModulation (per-voice volume), 2 = PitchModulation
const var GAIN_CHAIN = 1;
const var PITCH_CHAIN = 2;

inline function connectModulation(source, target, chainIndex, name)
{
    if (!isDefined(target) || target.getId() == "")
    {
        Console.print("Invalid modulation target: " + name);
        return;
    }

    // addGlobalModulator provides per-voice modulation -
    // each voice gets its own modulation value from the global source
    local newMod = target.addGlobalModulator(chainIndex, source, name);

    // The returned Modulator handle controls the connection's intensity
    if (isDefined(newMod))
        newMod.setIntensity(1.0);
}

// Connect LFO1 to Oscillator1's gain chain (per-voice)
connectModulation(globalLFO1, osc1, GAIN_CHAIN, "LFO1_Osc1_Vol");

// Context: A modulation matrix decides at connection time whether to use
// per-voice (addGlobalModulator) or static (addStaticGlobalModulator)
// modulation based on the target type. Effect parameters and synth-level
// controls don't need per-voice resolution.

const var globalLFO = Synth.getModulator("GlobalLFO1");
const var globalCC = Synth.getModulator("GlobalCC");

const var oscGroup = Synth.getChildSynth("Oscillator1");

const var GAIN_CHAIN = 1;
const var PITCH_CHAIN = 2;

inline function addModConnection(source, target, chainIndex, name, useStatic)
{
    local newMod;

    if (useStatic)
    {
        // Static: one value per audio block, shared across all voices.
        // More CPU-efficient for targets like effect parameters, FM depth,
        // or any control that doesn't need per-voice independence.
        newMod = target.addStaticGlobalModulator(chainIndex, source, name);
    }
    else
    {
        // Per-voice: each voice gets its own modulation value.
        // Required for gain/pitch chains where voice independence matters
        // (e.g., per-voice tremolo or vibrato).
        newMod = target.addGlobalModulator(chainIndex, source, name);
    }

    if (isDefined(newMod))
        newMod.setIntensity(1.0);

    return newMod;
}

// CC modulation on gain chain: static is sufficient (no per-voice needed)
addModConnection(globalCC, oscGroup, GAIN_CHAIN, "CC_Vol", true);

// LFO on pitch chain: per-voice for independent vibrato per voice
addModConnection(globalLFO, oscGroup, PITCH_CHAIN, "LFO_Pitch", false);

// Context: A multi-articulation instrument stores child synths by name
// and uses asSampler() to access Sampler-specific methods like
// loadSampleMap() and enableRoundRobin().

const var articulationIds = ["sustain", "staccato", "transitions"];
const var childSynths = {};

for (id in articulationIds)
    childSynths[id] = Synth.getChildSynth(id);

inline function loadPatch(patchName)
{
    for (id in articulationIds)
    {
        // asSampler() returns undefined if the child is not a ModulatorSampler
        local sampler = childSynths[id].asSampler();

        if (isDefined(sampler))
            sampler.loadSampleMap(patchName + "_" + id);
    }
}

// Configure round-robin on a specific articulation
childSynths["staccato"].asSampler().enableRoundRobin(false);

// Context: An "FX lock" feature saves the current state of effects before a
// preset loads, then restores them afterward. exportState captures the
// complete processor state as a base64 string that can be stored in a
// variable or serialized to JSON.

const var fx = Synth.getEffect("MasterEQ");
const var compressor = Synth.getEffect("MasterComp");

// Store state objects for each lockable effect
var fxStates = [{ FX: fx, State: "" },
                { FX: compressor, State: "" }];

// Before a preset loads: snapshot states of locked effects
inline function onPresetPreLoad()
{
    for (item in fxStates)
        item.State = item.FX.exportState();
}

// After a preset loads: restore the snapshots
inline function onPresetPostLoad()
{
    for (item in fxStates)
    {
        if (item.State.length > 0)
            item.FX.restoreState(item.State);
    }
}

// Context: Export each effect's base64 state into a JSON object for
// saving/loading custom FX chain configurations to disk.

const var effects = [Synth.getEffect("EQ"),
                     Synth.getEffect("Compressor"),
                     Synth.getEffect("Reverb")];

inline function saveFXChain(file)
{
    local content = {};

    for (fx in effects)
        content[fx.getId()] = fx.exportState();

    file.writeObject(content);
}

// Context: A ScriptPanel timer polls child synth levels and applies
// decay smoothing for stable meter display. Peak hold shows
// the recent maximum for a fixed number of frames.

const var meterPanel = Content.getComponent("MeterPanel");
const var synth1 = Synth.getChildSynth("Channel1");

const var DECAY = 0.85;
const var PEAK_HOLD_FRAMES = 30;

meterPanel.data.left = 0.0;
meterPanel.data.right = 0.0;
meterPanel.data.leftMax = 0.0;
meterPanel.data.maxCounter = 0;

meterPanel.setTimerCallback(function()
{
    // getCurrentLevel returns display values (UI refresh rate, not sample-accurate)
    local l = Math.min(1.0, this.data.synth.getCurrentLevel(true));
    local r = Math.min(1.0, this.data.synth.getCurrentLevel(false));

    // Attack/decay smoothing: fast attack, slow decay
    if (l > this.data.left)
        this.data.left = this.data.left * 0.3 + 0.7 * l;
    else
        this.data.left *= DECAY;

    // Peak hold: remember maximum for N frames
    if (l > this.data.leftMax)
    {
        this.data.leftMax = l;
        this.data.maxCounter = PEAK_HOLD_FRAMES;
    }

    if (--this.data.maxCounter <= 0)
        this.data.leftMax = 0.0;

    this.repaint();
});

meterPanel.data.synth = synth1;
meterPanel.startTimer(30);

// Context: A signal routing visualizer checks whether each oscillator
// group is producing audio to highlight active signal paths.

const var oscGroups = [Synth.getChildSynth("OSC1"),
                       Synth.getChildSynth("OSC2")];

// In a timer callback:
inline function isOscActive(index)
{
    return oscGroups[index].getCurrentLevel(true) > 0;
}

// Context: A multi-output plugin routes different child synths to separate
// stereo output pairs. The routing matrix is obtained from the child synth
// and connections are configured based on a user-selectable output selector.

const var childSynth = Synth.getChildSynth("Generator1");
const var matrix = childSynth.getRoutingMatrix();

inline function onOutputSelectorControl(component, value)
{
    local outputPair = parseInt(value) - 1;
    local destL = outputPair * 2;
    local destR = outputPair * 2 + 1;

    matrix.addConnection(0, destL);

    // addConnection returns false if the output channel doesn't exist
    local success = matrix.addConnection(1, destR);

    if (!success)
    {
        // Fall back to stereo output 1+2 if the host doesn't support multichannel
        matrix.addConnection(0, 0);
        matrix.addConnection(1, 1);
    }
}

// Context: After a preset loads, restore previously saved base64 state
// strings to preserve the user's FX settings. Also update any connected
// UI components to reflect the restored processor state.

const var eq = Synth.getEffect("ChannelEQ");

// Saved state from a previous exportState() call
var savedEqState = "";

inline function lockEQ()
{
    savedEqState = eq.exportState();
}

inline function restoreLockedEQ()
{
    if (savedEqState.length > 0)
    {
        eq.restoreState(savedEqState);

        // After restoring, sync the UI with the processor state
        uph.updateConnectedComponentsFromModuleState();
    }
}

// Context: When programmatically building the module tree with the Builder API,
// newly created effects can be initialized to a known default state
// using a pre-captured base64 string.

const var b = Synth.createBuilder();

// A base64 string captured from a configured EQ module
const var DEFAULT_EQ_STATE = "516.3oc..."; // (truncated for brevity)

// During Builder construction:
b.flush("const var eq = b.create(b.Effects.CurveEq, \"MasterEQ\", 0, b.ChainIndexes.FX);", []);
b.flush("b.get(eq, b.InterfaceTypes.Effect).restoreState(DEFAULT_EQ_STATE);", []);

// Context: A multi-channel instrument stores ChildSynth references in an array
// and drives parameters from UI knobs in a loop.

const var NUM_CHANNELS = 4;
const var channels = [];

for (i = 0; i < NUM_CHANNELS; i++)
    channels[i] = Synth.getChildSynth("Channel" + (i + 1));

// Control per-channel gain from an array of knobs
inline function onGainKnobChanged(component, value)
{
    local idx = component.get("id").getTrailingIntValue() - 1;

    // Use dynamic constants instead of raw index numbers
    channels[idx].setAttribute(channels[idx].Gain, value);
}

// Context: ChildSynth dynamic constants extend beyond the base four parameters.
// A SynthGroup child exposes parameters like FM depth or detune that
// the parent script controls directly.

const var osc1 = Synth.getChildSynth("Oscillator1");
const var osc2 = Synth.getChildSynth("Oscillator2");

// Parameter indices are registered as dynamic constants on each instance.
// For a SynthGroup these might include Detune (4) and Spread (5)
// in addition to the base Gain (0), Balance (1), VoiceLimit (2), KillFadeTime (3).
inline function onDetuneChanged(component, value)
{
    local idx = parseInt(component.get("id").getTrailingIntValue()) - 1;
    local targets = [osc1, osc2];
    targets[idx].setAttribute(4, value);
}

// Context: A piano plugin has multiple sound layers (sustain, release, pedal,
// hammer noise) that are enabled or disabled based on a performance mode.
// A mode matrix defines which layers are active in each mode.

const var layers = [Synth.getChildSynth("Sustain"),
                    Synth.getChildSynth("Release"),
                    Synth.getChildSynth("PedalNoise"),
                    Synth.getChildSynth("HammerNoise")];

//                    Sustain  Release  Pedal  Hammer
const MODE_MATRIX = [[false,   false,   false, false],   // Full
                     [false,   false,   true,  true],     // Simple
                     [false,   true,    true,  true]];    // Minimal

inline function setMode(modeIndex)
{
    for (i = 0; i < layers.length; i++)
        layers[i].setBypassed(MODE_MATRIX[modeIndex][i]);
}

// Context: When loading a new patch, bypass any sampler that has no
// matching sample map and enable those that do.

const var articulationIds = ["sustain", "staccato", "legato"];
const var articulationSynths = [];

for (i = 0; i < articulationIds.length; i++)
    articulationSynths[i] = Synth.getChildSynth(articulationIds[i]);

inline function loadPatch(patchName)
{
    local availableMaps = Sampler.getSampleMapList();

    for (i = 0; i < articulationIds.length; i++)
    {
        local mapName = patchName + "_" + articulationIds[i];
        local hasMap = availableMaps.contains(mapName);

        articulationSynths[i].setBypassed(!hasMap);

        if (hasMap)
            articulationSynths[i].asSampler().loadSampleMap(mapName);
    }
}

