    local categories = FileSystem.findFiles(irRoot, "*", false);
    local result = {};

    for (c in categories)
    {
        if (!c.isDirectory())
            continue;

        local catName = c.toString(1);
        local irFiles = FileSystem.findFiles(c, "*.wav", false);
        local entries = [];

        for (i = 0; i < irFiles.length; i++)
        {
            local thisFile = irFiles[i];
