            local durationMs = (thisFile.getSize() / 6) / 48;

            entries.push({
                "Name": thisFile.toString(1),
                "Path": thisFile.toString(0),
                "Duration": durationMs
            });
        }

        result[catName] = entries;
    }

    return result;
}

