const var presetTable = Content.addViewport("PresetTable", 0, 0);

// ... setTableMode / setTableColumns / setTableCallback in onInit ...

// Build row data from file list
inline function buildRowData(fileList)
{
    local rows = [];

    for (f in fileList)
    {
        rows.push({
            "Name": f.toString(0),
            "Category": f.getParentDirectory().toString(0),
            "BPM": "120",
            "FullPath": f.toString(1),
            "Favorite": false
        });
    }

    return rows;
};

// Refresh the table at runtime (called from filter/search callbacks)
inline function refreshTable(fileList)
{
    local rows = buildRowData(fileList);
    presetTable.setTableRowData(rows);
};

// Context: Each row represents a modulation connection. Slider cells
//          receive a data object with Value, min, max, and style
//          properties instead of a plain number, enabling the table
//          to render the slider with the correct range.

// Rebuild rows from the modulation model
inline function rebuildModRows()
{
    local connections = [];  // from modulation engine
    local rows = [];

    for (c in connections)
    {
        rows.push({
            "Source": c.sourceName,
            "Target": c.targetName,
            "Intensity": {
                "Value": c.intensity,
                "min": -1.0,
                "max": 1.0,
                "style": "Knob"
            },
            "Mode": c.valueMode,
            "Delete": false
        });
    }

    modTable.setTableRowData(rows);
};

// Case-insensitive string sort
inline function caseInsensitiveSort(a, b)
{
    local aLower = a.toLowerCase();
    local bLower = b.toLowerCase();

    if (aLower < bLower) return -1;
    if (aLower > bLower) return 1;
    return 0;
};

Viewport1.setTableSortFunction(caseInsensitiveSort);

// Context: After loading content, find the matching row in a sorted table
//          and select it. Use getOriginalRowIndex() to map between the
//          sorted display order and the original data order, then call
//          setValue([column, row]) to highlight the active cell.

const var table = Content.addViewport("DataTable", 0, 0);

// ... setTableMode with MultiColumnMode: true ...

var rowData = [];

// Select a specific item by its original data index
inline function selectByOriginalIndex(targetOriginalIndex)
{
    for (i = 0; i < rowData.length; i++)
    {
        if (table.getOriginalRowIndex(i) == targetOriginalIndex)
        {
            // Select column 1, display row i
            table.setValue([1, i]);

            // Scroll so the selected row is visible
            table.set("viewPositionY", (i + 1) / rowData.length);
            table.sendRepaintMessage();
            return;
        }
    }

    // No match -- deselect
    table.setValue([-1, -1]);
    table.sendRepaintMessage();
};

